<section class="sim-panel" data-step-panel="0"><header class="sim-panel-head"><span class="sim-panel-head-icon"><i class="ph-duotone ph-wallet"></i></span><div><span class="sim-eyebrow">Etapa 1 de 3</span><h2>Quanto você quer usar?</h2><p>Este valor é o limite total. A soma de todos os produtos nunca poderá ultrapassá-lo.</p></div></header><div class="sim-panel-body"><div class="sim-quota-overview"><div class="sim-quota-overview-copy"><strong>Saldo disponível no projeto</strong><span>Valor real disponível para esta simulação.</span></div><strong class="sim-quota-overview-value" id="sim-real-remaining">Carregando...</strong></div><div class="sim-choice-grid"><button class="sim-choice" type="button" data-quota-mode="remaining"><span class="sim-choice-icon"><i class="ph-duotone ph-wallet"></i></span><span class="sim-choice-copy"><strong>Usar saldo disponível</strong><small id="sim-remaining-label">Carregando...</small></span><i class="sim-choice-check ph ph-circle" data-choice-check="remaining"></i></button><button class="sim-choice" type="button" data-quota-mode="custom"><span class="sim-choice-icon"><i class="ph-duotone ph-pencil-simple-line"></i></span><span class="sim-choice-copy"><strong>Simular outro valor</strong><small>Para comparar um cenário diferente.</small></span><i class="sim-choice-check ph ph-circle" data-choice-check="custom"></i></button></div><div class="sim-custom-card" id="sim-custom-quota-field" hidden><div class="sim-field"><label for="sim-custom-quota">Valor da simulação</label><input class="sim-input sim-money-input" id="sim-custom-quota" type="number" min="0.01" step="0.01" inputmode="decimal" placeholder="0,00"></div><div class="sim-custom-preview"><span>Limite escolhido</span><strong id="sim-quota-preview">R$ 0,00</strong></div></div><div class="sim-note warning" id="sim-custom-warning" hidden><i class="ph-duotone ph-warning"></i><span>O valor personalizado está acima do saldo real. A simulação continua possível, mas representa um cenário hipotético.</span></div><p class="sim-feedback" id="sim-quota-error" hidden></p><details class="sim-history" id="sim-history" hidden><summary><span class="sim-history-icon"><i class="ph-duotone ph-clock-counter-clockwise"></i></span><span class="sim-history-copy"><strong>Simulações salvas</strong><span id="sim-history-count"></span></span><i class="sim-history-caret ph ph-caret-down"></i></summary><div class="sim-history-body"><div class="sim-history-toolbar"><button class="sim-small-button danger" type="button" id="sim-clear-history"><i class="ph ph-trash"></i> Limpar histórico</button></div><div class="sim-history-list" id="sim-history-list"></div></div></details></div></section>
<section class="sim-panel" data-step-panel="1" hidden><header class="sim-panel-head"><span class="sim-panel-head-icon blue"><i class="ph-duotone ph-package"></i></span><div><span class="sim-eyebrow">Etapa 2 de 3</span><h2>Escolha os produtos</h2><p>Você pode selecionar vários. Na próxima etapa a cota será dividida entre eles.</p></div></header><div class="sim-panel-body"><div class="sim-product-tools"><div class="sim-search-wrap"><i class="ph ph-magnifying-glass"></i><input class="sim-search" id="sim-product-search" type="search" autocomplete="off" placeholder="Buscar produto..."></div><div class="sim-segmented" aria-label="Filtrar produtos"><button class="is-active" type="button" data-product-filter="enabled">Liberados</button><button type="button" data-product-filter="all">Todos</button></div></div><div class="sim-selection-status"><span class="sim-selected-badge"><i class="ph ph-check-circle"></i><strong id="sim-selected-count">0</strong> selecionado(s)</span><span id="sim-product-result-count"></span></div><div class="sim-product-list" id="sim-product-list"></div><p class="sim-feedback" id="sim-products-error" hidden></p></div></section>
<section class="sim-panel" data-step-panel="2" hidden><header class="sim-panel-head"><span class="sim-panel-head-icon green"><i class="ph-duotone ph-scales"></i></span><div><span class="sim-eyebrow">Etapa 3 de 3</span><h2>Defina as quantidades</h2><p>Cada produto mostra quanto ainda pode ser entregue. O total combinado nunca ultrapassa a cota.</p></div></header><div class="sim-panel-body"><div class="sim-summary" id="sim-summary"><div class="sim-summary-item"><span>Cota escolhida</span><strong id="sim-budget">R$ 0,00</strong></div><div class="sim-summary-item"><span>Já usado</span><strong id="sim-total">R$ 0,00</strong></div><div class="sim-summary-item available"><span>Você ainda pode usar</span><strong id="sim-balance">R$ 0,00</strong></div><div class="sim-progress"><span id="sim-progress"></span></div><div class="sim-budget-rule"><i class="ph ph-lock-simple"></i>O simulador impede que a soma dos produtos ultrapasse a cota escolhida.</div></div><div class="sim-allocation-list" id="sim-allocation-list"></div></div></section>
</main>
<div class="sim-action-bar" aria-label="Ações da simulação"><div class="sim-action-inner"><button class="sim-button back" type="button" id="sim-previous" hidden><i class="ph ph-arrow-left"></i><span>Voltar</span></button><button class="sim-button primary" type="button" id="sim-next">Escolher produtos <i class="ph ph-arrow-right"></i></button><button class="sim-button success final-action" type="button" id="sim-save" hidden><i class="ph-duotone ph-image-square"></i><span>Salvar imagem</span></button><button class="sim-button share final-action" type="button" id="sim-share" hidden><i class="ph-duotone ph-share-network"></i><span>Compartilhar</span></button></div></div><div class="sim-toast" id="sim-toast" role="status" aria-live="polite" hidden></div>
@endsection

@push('scripts')
<script>
(()=>{'use strict';const root=document.getElementById('delivery-simulator');if(!root)return;const PROJECT_TITLE=@json($project->title),EPS=.0005;const state={step:0,products:[],summary:{},quotaMode:'remaining',customQuota:0,productFilter:'enabled',search:'',selected:new Map(),history:[]};const historyKey=root.dataset.historyKey;const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(v||0));const qty=v=>new Intl.NumberFormat('pt-BR',{minimumFractionDigits:0,maximumFractionDigits:3}).format(Number(v||0));const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'})[c]);const floor3=v=>Math.max(0,Math.floor((Number(v||0)+1e-9)*1000)/1000);const panels=[...document.querySelectorAll('[data-step-panel]')],markers=[...document.querySelectorAll('[data-step-marker]')],prev=document.getElementById('sim-previous'),next=document.getElementById('sim-next'),save=document.getElementById('sim-save'),share=document.getElementById('sim-share');
function quotaValue(){return state.quotaMode==='remaining'?Math.max(0,Number(state.summary.financial_remaining||0)):Math.max(0,Number(state.customQuota||0))}function productFor(id){return state.products.find(p=>Number(p.product_id)===Number(id))}function destinationFor(entry,product){return(product?.destinations||[]).find(d=>Number(d.customer_id)===Number(entry.destinationId))||[...(product?.destinations||[])].sort((a,b)=>Number(b.price)-Number(a.price))[0]||null}function rows(){return[...state.selected.values()].map(entry=>{const product=productFor(entry.productId),destination=destinationFor(entry,product),price=Number(destination?.price||0),amount=Math.max(0,Number(entry.quantity||0));return{entry,product,destination,price,quantity:amount,total:amount*price}}).filter(r=>r.product&&r.destination&&r.price>0)}function totals(){const r=rows();return{rows:r,total:r.reduce((s,x)=>s+x.total,0)}}function configuredLimit(product){if(!product?.delivery_enabled||product.remaining_quantity===null||product.remaining_quantity===undefined)return Infinity;return Math.max(0,Number(product.remaining_quantity||0))}
function maxQuantityFor(productId){const product=productFor(productId),entry=state.selected.get(Number(productId));if(!product||!entry)return 0;const dest=destinationFor(entry,product),price=Number(dest?.price||0);if(!(price>0))return 0;const other=rows().reduce((sum,row)=>Number(row.entry.productId)===Number(productId)?sum:sum+row.total,0);const remainingBudget=Math.max(0,quotaValue()-other),byBudget=remainingBudget/price;return floor3(Math.min(byBudget,configuredLimit(product)))}function clampEntry(id,notify=false){const entry=state.selected.get(Number(id));if(!entry)return;const before=Math.max(0,Number(entry.quantity||0)),max=maxQuantityFor(id);entry.quantity=Math.min(before,max);if(notify&&before>max+EPS)toast(`Quantidade ajustada para o máximo: ${qty(max)} ${productFor(id)?.unit||'un'}.`)}function clampAll(){for(let pass=0;pass<2;pass++)for(const id of state.selected.keys())clampEntry(id)}function toast(message){const el=document.getElementById('sim-toast');el.textContent=message;el.hidden=false;clearTimeout(toast.t);toast.t=setTimeout(()=>el.hidden=true,3000)}
function renderStep(){panels.forEach(p=>p.hidden=Number(p.dataset.stepPanel)!==state.step);markers.forEach(m=>{const s=Number(m.dataset.stepMarker);m.classList.toggle('is-complete',s<=state.step);m.classList.toggle('is-current',s===state.step)});prev.hidden=state.step===0;next.hidden=state.step===2;save.hidden=state.step!==2;share.hidden=state.step!==2;next.innerHTML=state.step===1?'Definir quantidades <i class="ph ph-arrow-right"></i>':'Escolher produtos <i class="ph ph-arrow-right"></i>';if(state.step===0)renderQuota();if(state.step===1)renderProducts();if(state.step===2){clampAll();renderSimulation()}window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
function renderQuota(){const raw=state.summary.financial_remaining,remaining=raw===null||raw===undefined?null:Number(raw),available=remaining!==null&&remaining>0,rb=document.querySelector('[data-quota-mode="remaining"]'),cb=document.querySelector('[data-quota-mode="custom"]');rb.disabled=!available;if(!available&&state.quotaMode==='remaining')state.quotaMode='custom';rb.classList.toggle('is-active',state.quotaMode==='remaining');cb.classList.toggle('is-active',state.quotaMode==='custom');document.querySelectorAll('[data-choice-check]').forEach(i=>i.className=`sim-choice-check ph ${i.dataset.choiceCheck===state.quotaMode?'ph-check-circle-fill':'ph-circle'}`);document.getElementById('sim-real-remaining').textContent=remaining===null?'Não definido':money(Math.max(0,remaining));document.getElementById('sim-remaining-label').textContent=remaining===null?'Este projeto não possui saldo financeiro definido.':remaining>0?`${money(remaining)} disponíveis agora`:'Não há saldo disponível agora.';document.getElementById('sim-custom-quota-field').hidden=state.quotaMode!=='custom';const input=document.getElementById('sim-custom-quota');if(document.activeElement!==input)input.value=state.customQuota>0?state.customQuota:'';document.getElementById('sim-quota-preview').textContent=money(quotaValue());document.getElementById('sim-custom-warning').hidden=!(state.quotaMode==='custom'&&remaining!==null&&state.customQuota>remaining+.005)}
function renderProducts(){const search=state.search.trim().toLocaleLowerCase('pt-BR'),filtered=state.products.filter(p=>(search!==''||state.productFilter==='all'||p.delivery_enabled)&&(!search||`${p.product_name} ${p.unit}`.toLocaleLowerCase('pt-BR').includes(search))),visible=filtered.slice(0,48);document.getElementById('sim-selected-count').textContent=state.selected.size;document.getElementById('sim-product-result-count').textContent=visible.length<filtered.length?`${visible.length} de ${filtered.length} produto(s)`:`${filtered.length} produto(s)`;document.querySelectorAll('[data-product-filter]').forEach(b=>b.classList.toggle('is-active',b.dataset.productFilter===state.productFilter));document.getElementById('sim-product-list').innerHTML=visible.length?visible.map(p=>{const id=Number(p.product_id),selected=state.selected.has(id),limit=p.delivery_enabled&&p.remaining_quantity!==null&&p.remaining_quantity!==undefined?`<span class="sim-product-badge limit">Até ${qty(p.remaining_quantity)} ${esc(p.unit||'')}</span>`:'';return`<button class="sim-product-option ${selected?'is-selected':''}" type="button" data-product-id="${id}" aria-pressed="${selected}"><span class="sim-product-option-icon"><i class="ph-duotone ${p.delivery_enabled?'ph-check-circle':'ph-package'}"></i></span><span class="sim-product-option-copy"><strong>${esc(p.product_name)}</strong><small>${esc(p.price_label)} · ${esc(p.unit||'un')}</small><span class="sim-product-badges">${p.delivery_enabled?'<span class="sim-product-badge">Liberado</span>':''}${limit}</span></span><i class="ph ${selected?'ph-check-circle-fill':'ph-circle'} sim-product-option-check"></i></button>`}).join(''):'<div class="sim-empty">Nenhum produto encontrado neste filtro.</div>'}
function capacityDescription(row){const configured=configuredLimit(row.product);const other=rows().reduce((s,x)=>Number(x.entry.productId)===Number(row.entry.productId)?s:s+x.total,0),byBudget=row.price>0?Math.max(0,(quotaValue()-other)/row.price):0;if(Number.isFinite(configured)&&configured<=byBudget+EPS)return'Limite definido para este produto.';return state.selected.size>1?'Considerando a cota restante após os outros produtos.':'Considerando a cota escolhida e o preço atual.'}
function renderSimulation(){clampAll();const result=totals(),budget=quotaValue(),available=Math.max(0,budget-result.total);document.getElementById('sim-budget').textContent=money(budget);document.getElementById('sim-total').textContent=money(result.total);document.getElementById('sim-balance').textContent=money(available);document.getElementById('sim-progress').style.width=`${budget>0?Math.min(100,result.total/budget*100):0}%`;document.getElementById('sim-allocation-list').innerHTML=result.rows.length?result.rows.map(row=>{const id=Number(row.product.product_id),max=maxQuantityFor(id),options=(row.product.destinations||[]).map(d=>`<option value="${Number(d.customer_id)}" ${Number(d.customer_id)===Number(row.destination.customer_id)?'selected':''}>${esc(d.customer)} · ${money(d.price)}</option>`).join('');return`<article class="sim-allocation" data-allocation="${id}"><header class="sim-allocation-head"><span class="sim-allocation-icon"><i class="ph-duotone ph-package"></i></span><span class="sim-allocation-product"><strong>${esc(row.product.product_name)}</strong><span>${money(row.price)} por ${esc(row.product.unit||'un')}</span></span><strong class="sim-row-total" data-row-total="${id}">${money(row.total)}</strong></header><div class="sim-allocation-body"><div class="sim-capacity"><span class="sim-capacity-icon"><i class="ph-duotone ph-gauge"></i></span><span class="sim-capacity-copy"><strong>Você pode entregar até</strong><span data-capacity-description="${id}">${esc(capacityDescription(row))}</span></span><strong class="sim-capacity-value" data-capacity-value="${id}">${qty(max)} ${esc(row.product.unit||'un')}</strong></div><div class="sim-allocation-grid"><div class="sim-field"><label><span>Preço e destino</span></label><select class="sim-select" data-destination-product="${id}">${options}</select></div><div class="sim-field"><label><span>Quantidade (${esc(row.product.unit||'un')})</span><span data-current-max-label="${id}">máx. ${qty(max)}</span></label><div class="sim-quantity-control"><input class="sim-range" type="range" min="0" max="${Math.max(max,.001)}" step="0.001" value="${Math.min(row.quantity,max)}" data-range-product="${id}"><input class="sim-input sim-quantity-input" type="number" min="0" max="${max}" step="0.001" inputmode="decimal" value="${row.quantity||''}" data-quantity-product="${id}"></div></div></div><div class="sim-allocation-actions"><button class="sim-small-button primary-soft" type="button" data-fill-product="${id}"><i class="ph ph-arrow-line-up"></i> Usar máximo</button><button class="sim-small-button danger" type="button" data-remove-product="${id}"><i class="ph ph-trash"></i> Remover</button></div></div></article>`}).join(''):'<div class="sim-empty">Nenhum produto selecionado.</div>'}
function refreshSimulation(){clampAll();const result=totals(),budget=quotaValue(),available=Math.max(0,budget-result.total);document.getElementById('sim-total').textContent=money(result.total);document.getElementById('sim-balance').textContent=money(available);document.getElementById('sim-progress').style.width=`${budget>0?Math.min(100,result.total/budget*100):0}%`;result.rows.forEach(row=>{const id=Number(row.product.product_id),max=maxQuantityFor(id),total=document.querySelector(`[data-row-total="${id}"]`),cap=document.querySelector(`[data-capacity-value="${id}"]`),desc=document.querySelector(`[data-capacity-description="${id}"]`),label=document.querySelector(`[data-current-max-label="${id}"]`),range=document.querySelector(`[data-range-product="${id}"]`),input=document.querySelector(`[data-quantity-product="${id}"]`);if(total)total.textContent=money(row.total);if(cap)cap.textContent=`${qty(max)} ${row.product.unit||'un'}`;if(desc)desc.textContent=capacityDescription(row);if(label)label.textContent=`máx. ${qty(max)}`;if(range){range.max=Math.max(max,.001);if(document.activeElement!==range)range.value=Math.min(row.entry.quantity,max)}if(input){input.max=max;if(document.activeElement!==input)input.value=row.entry.quantity||''}})}
function updateQuantity(id,value){id=Number(id);const entry=state.selected.get(id);if(!entry)return;const parsed=value===''?0:Math.max(0,Number(String(value).replace(',','.'))||0);entry.quantity=parsed;const max=maxQuantityFor(id);if(parsed>max+EPS){entry.quantity=max;toast(`Máximo para este produto: ${qty(max)} ${productFor(id)?.unit||'un'}.`)}else entry.quantity=floor3(parsed);const range=document.querySelector(`[data-range-product="${id}"]`),input=document.querySelector(`[data-quantity-product="${id}"]`);if(range&&document.activeElement!==range)range.value=entry.quantity;if(input&&document.activeElement!==input)input.value=entry.quantity||'';refreshSimulation()}
function validate(){document.getElementById('sim-quota-error').hidden=true;document.getElementById('sim-products-error').hidden=true;if(state.step===0&&quotaValue()<=0){const e=document.getElementById('sim-quota-error');e.textContent='Informe um valor maior que zero para continuar.';e.hidden=false;return false}if(state.step===1&&state.selected.size===0){const e=document.getElementById('sim-products-error');e.textContent='Selecione pelo menos um produto.';e.hidden=false;return false}return true}
function readHistory(){try{const parsed=JSON.parse(localStorage.getItem(historyKey)||'[]'),cutoff=Date.now()-30*24*60*60*1000;state.history=Array.isArray(parsed)?parsed.filter(i=>Number(i.createdAt)>=cutoff&&Array.isArray(i.rows)&&/^data:image\/(?:webp|png);base64,/i.test(String(i.image||''))).slice(0,4):[]}catch{state.history=[]}renderHistory()}function persistHistory(){try{localStorage.setItem(historyKey,JSON.stringify(state.history.slice(0,4)));return true}catch{toast('Não foi possível salvar a imagem neste dispositivo.');return false}}function renderHistory(){const section=document.getElementById('sim-history');section.hidden=state.history.length===0;document.getElementById('sim-history-count').textContent=`${state.history.length} ${state.history.length===1?'imagem salva':'imagens salvas'}`;document.getElementById('sim-history-list').innerHTML=state.history.map(item=>`<article class="sim-history-card"><img src="${item.image}" alt="Prévia da simulação salva"><div class="sim-history-card-body"><strong>${money(item.total)} em ${item.rows.length} produto(s)</strong><span>${new Date(item.createdAt).toLocaleString('pt-BR')}</span><div class="sim-history-actions"><button class="sim-small-button" type="button" data-open-history="${item.id}">Abrir</button><button class="sim-small-button" type="button" data-download-history="${item.id}"><i class="ph ph-download-simple"></i> Baixar</button><button class="sim-small-button primary-soft" type="button" data-share-history="${item.id}"><i class="ph ph-share-network"></i> Compartilhar</button><button class="sim-small-button danger" type="button" data-delete-history="${item.id}"><i class="ph ph-trash"></i></button></div></div></article>`).join('')}
function snapshotImage(result,budget){const visible=result.rows.slice(0,12),canvas=document.createElement('canvas');canvas.width=900;canvas.height=316+visible.length*64+(result.rows.length>12?42:0);const c=canvas.getContext('2d'),g=c.createLinearGradient(0,0,900,0);g.addColorStop(0,'#168a4d');g.addColorStop(.5,'#7c3aed');g.addColorStop(1,'#2563eb');c.fillStyle='#fff';c.fillRect(0,0,900,canvas.height);c.fillStyle=g;c.fillRect(0,0,900,12);c.fillStyle='#102018';c.font='700 30px Arial';c.fillText('Simulação de entrega',48,65);c.fillStyle='#52645a';c.font='18px Arial';c.fillText(PROJECT_TITLE,48,98);c.fillStyle='#f7faf8';c.fillRect(48,126,804,112);const available=Math.max(0,budget-result.total);c.fillStyle='#809087';c.font='15px Arial';c.fillText('Cota',72,160);c.fillText('Usado',330,160);c.fillText('Disponível',594,160);c.fillStyle='#102018';c.font='700 22px Arial';c.fillText(money(budget),72,200);c.fillText(money(result.total),330,200);c.fillStyle='#168a4d';c.fillText(money(available),594,200);visible.forEach((row,i)=>{const y=282+i*64;c.strokeStyle='#dce7e0';c.beginPath();c.moveTo(48,y+35);c.lineTo(852,y+35);c.stroke();c.fillStyle='#102018';c.font='700 17px Arial';c.fillText(String(row.product.product_name).slice(0,40),48,y);c.fillStyle='#52645a';c.font='16px Arial';c.fillText(`${qty(row.quantity)} ${row.product.unit||'un'}`,500,y);c.fillStyle='#168a4d';c.font='700 17px Arial';c.textAlign='right';c.fillText(money(row.total),852,y);c.textAlign='left'});if(result.rows.length>12){c.fillStyle='#52645a';c.font='16px Arial';c.fillText(`+ ${result.rows.length-12} produto(s)`,48,canvas.height-22)}return canvas.toDataURL('image/webp',.82)}
function currentSnapshot(){const result=totals();if(!result.rows.some(row=>row.quantity>EPS))return null;const budget=quotaValue();return{id:`${Date.now()}-${Math.random().toString(36).slice(2,7)}`,createdAt:Date.now(),quotaMode:state.quotaMode,customQuota:state.customQuota,budget,total:result.total,rows:result.rows.map(r=>({productId:Number(r.product.product_id),destinationId:Number(r.destination.customer_id),quantity:r.quantity})),image:snapshotImage(result,budget)}}function saveSnapshot(){const item=currentSnapshot();if(!item){toast('Adicione uma quantidade antes de salvar.');return}state.history=[item,...state.history].slice(0,4);if(persistHistory()){renderHistory();toast('Imagem salva neste dispositivo.')}}function restoreHistory(item){state.quotaMode='custom';state.customQuota=Number(item.budget||item.customQuota||0);state.selected.clear();item.rows.forEach(r=>{if(productFor(r.productId))state.selected.set(Number(r.productId),{productId:Number(r.productId),destinationId:Number(r.destinationId),quantity:Number(r.quantity||0)})});clampAll();state.step=2;renderStep()}function downloadDataUrl(data,createdAt=Date.now()){const a=document.createElement('a');a.href=data;a.download=`simulacao-entrega-${new Date(createdAt).toISOString().slice(0,10)}.${data.startsWith('data:image/png')?'png':'webp'}`;document.body.appendChild(a);a.click();a.remove()}function downloadImage(item){downloadDataUrl(item.image,item.createdAt)}async function dataUrlToFile(data,createdAt){const blob=await(await fetch(data)).blob(),ext=blob.type==='image/png'?'png':'webp';return new File([blob],`simulacao-entrega-${new Date(createdAt).toISOString().slice(0,10)}.${ext}`,{type:blob.type||'image/webp'})}async function shareImage(item){if(!item?.image)return;try{const file=await dataUrlToFile(item.image,item.createdAt),shareData={title:'Simulação de entrega',text:PROJECT_TITLE,files:[file]},supported=typeof navigator.share==='function'&&(typeof navigator.canShare!=='function'||navigator.canShare(shareData));if(supported){await navigator.share(shareData);return}downloadImage(item);toast('Este navegador não compartilha arquivos diretamente. A imagem foi baixada.')}catch(e){if(e?.name!=='AbortError')toast('Não foi possível compartilhar a imagem.')}}async function shareCurrent(){const item=currentSnapshot();if(!item){toast('Adicione uma quantidade antes de compartilhar.');return}await shareImage(item)}
root.addEventListener('click',e=>{const q=e.target.closest('[data-quota-mode]');if(q&&!q.disabled){state.quotaMode=q.dataset.quotaMode;clampAll();renderQuota()}const f=e.target.closest('[data-product-filter]');if(f){state.productFilter=f.dataset.productFilter;renderProducts()}const p=e.target.closest('[data-product-id]');if(p){const id=Number(p.dataset.productId);if(state.selected.has(id))state.selected.delete(id);else{const product=productFor(id),dest=[...(product?.destinations||[])].sort((a,b)=>Number(b.price)-Number(a.price))[0];if(dest)state.selected.set(id,{productId:id,destinationId:Number(dest.customer_id),quantity:0})}renderProducts()}const fill=e.target.closest('[data-fill-product]');if(fill){const id=Number(fill.dataset.fillProduct),entry=state.selected.get(id);if(entry){entry.quantity=maxQuantityFor(id);renderSimulation()}}const rem=e.target.closest('[data-remove-product]');if(rem){state.selected.delete(Number(rem.dataset.removeProduct));renderSimulation()}});root.addEventListener('input',e=>{if(e.target.id==='sim-custom-quota'){state.customQuota=Math.max(0,Number(String(e.target.value).replace(',','.'))||0);clampAll();renderQuota()}if(e.target.id==='sim-product-search'){state.search=e.target.value||'';renderProducts()}if(e.target.matches('[data-range-product],[data-quantity-product]'))updateQuantity(e.target.dataset.rangeProduct||e.target.dataset.quantityProduct,e.target.value)});root.addEventListener('change',e=>{if(e.target.matches('[data-destination-product]')){const id=Number(e.target.dataset.destinationProduct),entry=state.selected.get(id);if(entry){entry.destinationId=Number(e.target.value);clampEntry(id,true);renderSimulation()}}});prev.addEventListener('click',()=>{if(state.step>0){state.step--;renderStep()}});next.addEventListener('click',()=>{if(validate()&&state.step<2){state.step++;renderStep()}});save.addEventListener('click',saveSnapshot);share.addEventListener('click',shareCurrent);document.getElementById('sim-restart').addEventListener('click',()=>{state.step=0;state.selected.clear();state.search='';state.productFilter='enabled';state.customQuota=0;state.quotaMode=state.summary.financial_remaining!==null&&Number(state.summary.financial_remaining)>0?'remaining':'custom';renderStep()});document.getElementById('sim-clear-history').addEventListener('click',()=>{state.history=[];localStorage.removeItem(historyKey);renderHistory()});document.getElementById('sim-history-list').addEventListener('click',e=>{const open=e.target.closest('[data-open-history]'),download=e.target.closest('[data-download-history]'),shareHistory=e.target.closest('[data-share-history]'),remove=e.target.closest('[data-delete-history]'),id=open?.dataset.openHistory||download?.dataset.downloadHistory||shareHistory?.dataset.shareHistory||remove?.dataset.deleteHistory,item=state.history.find(x=>x.id===id);if(open&&item)restoreHistory(item);if(download&&item)downloadImage(item);if(shareHistory&&item)shareImage(item);if(remove&&item){state.history=state.history.filter(x=>x.id!==id);persistHistory();renderHistory()}});
async function load(){next.disabled=true;try{const response=await fetch(root.dataset.endpoint,{headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},credentials:'same-origin',cache:'no-store'});if(!response.ok)throw new Error('Não foi possível carregar os dados deste projeto.');const data=await response.json();state.products=Array.isArray(data.products)?data.products:[];state.summary=data.summary||{};if(state.summary.financial_remaining===null||Number(state.summary.financial_remaining)<=0)state.quotaMode='custom';readHistory();renderStep()}catch(e){toast(e.message||'Não foi possível abrir o simulador.')}finally{next.disabled=false}}load();
})();
</script>
@endpush